style.css:
@-moz-document domain("roblox.com") {
/* Tło strony głównej i innych podstron */
    body {
        background: radial-gradient(circle, #4B0082, #2a003d);
        color: var(--textColor);
        font-family: 'Arial', sans-serif;
        margin: 0;
        padding: 0;
        overflow-x: hidden;
    }

    /* Zmiana kolorów nawigacji */
    #navigation, .navbar, .top-menu {
        background-color: rgba(75, 0, 130, 0.9);
        color: white !important;
        border-bottom: 2px solid #9b59b6;
    }

    /* Styl linków */
    a {
        color: #a569bd !important;
        text-decoration: none;
        transition: color 0.3s ease, text-shadow 0.3s ease;
    }

    a:hover {
        color: #ffffff !important;
        text-shadow: 0 0 10px #a569bd, 0 0 20px #ffffff;
    }

    /* Nagłówki */
    h1, h2, h3, h4, h5, h6 {
        text-shadow: 0 0 10px #9b59b6, 0 0 20px #4B0082;
    }

    /* Karty i sekcje */
    .card, .game-card, .section, .container {
        background: rgba(75, 0, 130, 0.8) !important;
        border: 1px solid #9b59b6;
        border-radius: 10px;
        box-shadow: 0 0 15px rgba(155, 89, 182, 0.5);
        color: white;
    }

    /* Gwiazdki tła */
    .star {
        position: absolute;
        background: radial-gradient(circle, #FFFFFF, #9b59b6 60%, transparent 80%);
        clip-path: polygon(
            50% 0%,
            61% 35%,
            98% 35%,
            68% 57%,
            79% 91%,
            50% 70%,
            21% 91%,
            32% 57%,
            2% 35%,
            39% 35%
        );
        box-shadow: 0 0 10px 5px #9b59b6, 0 0 30px 15px #4B0082;
        animation: twinkle 3s infinite alternate ease-in-out;
    }

    /* Dodanie wielu gwiazdek */
    body:before {
        content: '';
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        z-index: -1;
        background: radial-gradient(circle at 20% 30%, rgba(155, 89, 182, 0.8), transparent 70%),
                    radial-gradient(circle at 80% 70%, rgba(255, 255, 255, 0.6), transparent 60%),
                    radial-gradient(circle at 50% 50%, rgba(75, 0, 130, 0.4), transparent 80%);
        animation: move-background 10s linear infinite;
    }

    /* Animacja gwiazdek */
    @keyframes twinkle {
        0% {
            opacity: 1;
            transform: scale(1);
        }
        50% {
            opacity: 0.8;
            transform: scale(1.1);
        }
        100% {
            opacity: 1;
            transform: scale(1);
        }
    }

    /* Animacja tła */
    @keyframes move-background {
        0% {
            background-position: 0 0;
        }
        100% {
            background-position: 100% 100%;
        }
    }

    /* Przycisk logowania i rejestracji */
    .btn-primary, .btn-secondary {
        background-color: #9b59b6 !important;
        border: 1px solid #4B0082;
        color: white !important;
    }

    .btn-primary:hover, .btn-secondary:hover {
        background-color: #4B0082 !important;
        box-shadow: 0 0 10px 5px #a569bd;
    }
}
